#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<unsigned long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int half = n / 2;
    vector<unsigned long> left_part, right_part;

    // Recursive function to compute sums for the left part
    std::function<void(int, unsigned long)> compute_sums_left = [&](int i, unsigned long total) {
        if (i == half) {
            left_part.push_back(total);
        } else {
            compute_sums_left(i + 1, (total + a[i]) % m);
            compute_sums_left(i + 1, total);
        }
    };

    // Recursive function to compute sums for the right part
    std::function<void(int, unsigned long)> compute_sums_right = [&](int i, unsigned long total) {
        if (i == n) {
            right_part.push_back(total);
        } else {
            compute_sums_right(i + 1, (total + a[i]) % m);
            compute_sums_right(i + 1, total);
        }
    };

    compute_sums_left(0, 0);
    compute_sums_right(half, 0);

    unsigned long max_total = 0;

    // Remove duplicates and sort left_part
    std::set<unsigned long> left_set(left_part.begin(), left_part.end());
    std::vector<unsigned long> sorted_left(left_set.begin(), left_set.end());

    for (auto val : right_part) {
        auto it = std::lower_bound(sorted_left.begin(), sorted_left.end(), m - val);
        if (it != sorted_left.begin()) {
            auto candidate_it = it - 1;
            unsigned long candidate_sum = *candidate_it + val;
            if (candidate_sum > max_total) {
                max_total = candidate_sum;
            }
        }
    }

    cout << max_total << "\n";

    return 0;
}
